func run(args []string) error {
	opts := Options{
		AcceptedStatusCodes:   "200..300",
		BufferSize:            4096,
		MaxConnections:        512,
		MaxConnectionsPerHost: 512,
		MaxResponseBodySize:   10000000,
		MaxRedirections:       64,
		Timeout:               10,
		Format:                "text",
		Color:                 "auto",
	}

	// Manual flag parsing
	// We need to handle positional args.
	var positional []string

	// For error message for flag value type
	// Map from long to def
	longToDef := map[string]flagDef{}
	shortToDef := map[rune]flagDef{}
	for _, d := range flagDefs {
		longToDef[d.long] = d
		if d.short != 0 {
			shortToDef[d.short] = d
		}
	}

	// Helper to produce invalid argument error
	invalidArgError := func(def flagDef, val string, err error) string {
		// format: invalid argument for flag `-b, --buffer-size' (expected int): strconv.ParseInt: parsing "abc": invalid syntax
		var flagRepr string
		if def.short != 0 {
			flagRepr = fmt.Sprintf("`-%c, --%s'", def.short, def.long)
		} else {
			flagRepr = fmt.Sprintf("`--%s'", def.long)
		}
		exp := def.valueType
		if def.valueType == "int" {
			exp = "int"
		} else if def.valueType == "uint" {
			exp = "uint"
		}
		return fmt.Sprintf("invalid argument for flag %s (expected %s): %v", flagRepr, exp, err)
	}

	// Helper for invalid value error for format, color
	invalidValueError := func(long, val string, allowed []string) string {
		// Invalid value `xml' for option `--format'. Allowed values are: text, json or junit
		allowedStr := ""
		if len(allowed) == 3 {
			allowedStr = fmt.Sprintf("%s, %s or %s", allowed[0], allowed[1], allowed[2])
		} else {
			allowedStr = strings.Join(allowed, ", ")
		}
		return fmt.Sprintf("Invalid value `%s' for option `--%s'. Allowed values are: %s", val, long, allowedStr)
	}

	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			// rest positional
			positional = append(positional, args[i+1:]...)
			break
		}
		if strings.HasPrefix(arg, "--") {
			// long flag
			// split on =
			nameVal := arg[2:]
			var name, val string
			hasEq := false
			if idx := strings.Index(nameVal, "="); idx != -1 {
				name = nameVal[:idx]
				val = nameVal[idx+1:]
				hasEq = true
			} else {
				name = nameVal
			}
			def, ok := longToDef[name]
			if !ok {
				fmt.Fprintf(os.Stderr, "unknown flag `%s'\n", name)
				return fmt.Errorf("unknown flag")
			}
			if def.hasValue {
				if !hasEq {
					// need next arg as value unless boolean? but hasValue true means expects value
					i++
					if i >= len(args) {
						// go-flags would say expected value?
						// For simplicity, treat as invalid?
