						fmt.Fprintf(os.Stderr, "expected argument for flag `--%s'\n", name)
						return fmt.Errorf("expected arg")
					}
					val = args[i]
				}
				// Now parse according to type
				switch def.long {
				case "accepted-status-codes":
					opts.AcceptedStatusCodes = val
				case "buffer-size":
					iv, err := strconv.ParseInt(val, 10, 64)
					if err != nil {
						fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
						return fmt.Errorf("invalid")
					}
					opts.BufferSize = int(iv)
				case "max-connections":
					iv, err := strconv.ParseInt(val, 10, 64)
					if err != nil {
						fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
						return fmt.Errorf("invalid")
					}
					opts.MaxConnections = int(iv)
				case "max-connections-per-host":
					iv, err := strconv.ParseInt(val, 10, 64)
					if err != nil {
						fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
						return fmt.Errorf("invalid")
					}
					opts.MaxConnectionsPerHost = int(iv)
				case "max-response-body-size":
					iv, err := strconv.ParseInt(val, 10, 64)
					if err != nil {
						fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
						return fmt.Errorf("invalid")
					}
					opts.MaxResponseBodySize = int(iv)
				case "exclude":
					opts.Exclude = append(opts.Exclude, val)
				case "include":
					opts.Include = append(opts.Include, val)
				case "header":
					opts.Headers = append(opts.Headers, val)
				case "max-retries":
					uv, err := strconv.ParseUint(val, 10, 64)
					if err != nil {
						fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
						return fmt.Errorf("invalid")
					}
					opts.MaxRetries = uint(uv)
				case "dns-resolver":
					opts.DnsResolver = val
				case "format":
					// validate allowed
					lower := strings.ToLower(val)
					valid := false
					for _, a := range def.allowedVals {
						if a == lower {
							valid = true
							break
						}
					}
					if !valid {
						fmt.Fprintln(os.Stderr, invalidValueError(def.long, val, def.allowedVals))
						return fmt.Errorf("invalid")
					}
					opts.Format = lower
				case "max-redirections":
					iv, err := strconv.ParseInt(val, 10, 64)
					if err != nil {
						fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
						return fmt.Errorf("invalid")
					}
					opts.MaxRedirections = int(iv)
				case "rate-limit":
					iv, err := strconv.ParseInt(val, 10, 64)
					if err != nil {
						fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
						return fmt.Errorf("invalid")
					}
					opts.RateLimit = int(iv)
				case "timeout":
					iv, err := strconv.ParseInt(val, 10, 64)
					if err != nil {
						fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
						return fmt.Errorf("invalid")
					}
					opts.Timeout = int(iv)
				case "proxy":
					opts.Proxy = val
				case "color":
					lower := strings.ToLower(val)
					valid := false
					for _, a := range def.allowedVals {
						if a == lower {
							valid = true
							break
						}
					}
					if !valid {
						fmt.Fprintln(os.Stderr, invalidValueError(def.long, val, def.allowedVals))
						return fmt.Errorf("invalid")
					}
					opts.Color = lower
				}
			} else {
				// boolean flag, should not have =value, but if hasEq with value? go-flags allows --flag=value for bool? Probably not needed.
				// For boolean, presence sets true.
				if hasEq {
					// If value provided, maybe parse? But we treat as error? go-flags would treat as? For simplicity, if hasEq, we ignore and set true, unless value is "false" etc.
					// But we will support --flag=value where value is not needed? We'll still set.
				}
				switch def.long {
				case "follow-robots-txt":
					opts.FollowRobotsTxt = true
				case "follow-sitemap-xml":
					opts.FollowSitemapXml = true
				case "ignore-fragments":
					opts.IgnoreFragments = true
				case "json":
					opts.Json = true
				case "experimental-verbose-json":
					opts.ExperimentalVerboseJson = true
				case "junit":
					opts.Junit = true
				case "verbose":
					opts.Verbose = true
				case "skip-tls-verification":
					opts.SkipTLSVerification = true
				case "one-page-only":
					opts.OnePageOnly = true
				case "help":
					opts.Help = true
				case "version":
					opts.Version = true
				}
			}
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			// short flag(s) - could be combined? For simplicity, handle single short flag maybe with value.
			// Handle -b, -c, -e, -i, -f, -r, -t, -v, -h
			// For simplicity, iterate runes after -
			// If flag expects value, the rest of arg or next arg is value.
			shorts := arg[1:]
			for j, ch := range shorts {
				def, ok := shortToDef[ch]
				if !ok {
					fmt.Fprintf(os.Stderr, "unknown flag `%c'\n", ch)
					return fmt.Errorf("unknown flag")
				}
				if def.hasValue {
					var val string
					// If there are remaining chars in this arg, they are value
					if j+1 < len(shorts) {
						val = shorts[j+1:]
						// consume rest
						// No more short flags in this arg
						// Process this flag and break
						switch def.long {
						case "buffer-size":
							iv, err := strconv.ParseInt(val, 10, 64)
							if err != nil {
								fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
								return fmt.Errorf("invalid")
							}
							opts.BufferSize = int(iv)
						case "max-connections":
							iv, err := strconv.ParseInt(val, 10, 64)
							if err != nil {
								fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
								return fmt.Errorf("invalid")
							}
							opts.MaxConnections = int(iv)
						case "exclude":
							opts.Exclude = append(opts.Exclude, val)
						case "include":
							opts.Include = append(opts.Include, val)
						case "max-redirections":
							iv, err := strconv.ParseInt(val, 10, 64)
							if err != nil {
								fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
								return fmt.Errorf("invalid")
							}
							opts.MaxRedirections = int(iv)
						case "timeout":
							iv, err := strconv.ParseInt(val, 10, 64)
							if err != nil {
								fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
								return fmt.Errorf("invalid")
							}
							opts.Timeout = int(iv)
						}
						break // done with this arg
					} else {
						// value is next arg
						i++
						if i >= len(args) {
							fmt.Fprintf(os.Stderr, "expected argument for flag `-%c'\n", ch)
							return fmt.Errorf("expected arg")
						}
						val = args[i]
						switch def.long {
						case "buffer-size":
							iv, err := strconv.ParseInt(val, 10, 64)
							if err != nil {
								fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
								return fmt.Errorf("invalid")
							}
							opts.BufferSize = int(iv)
						case "max-connections":
							iv, err := strconv.ParseInt(val, 10, 64)
							if err != nil {
								fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
								return fmt.Errorf("invalid")
							}
							opts.MaxConnections = int(iv)
						case "exclude":
							opts.Exclude = append(opts.Exclude, val)
						case "include":
							opts.Include = append(opts.Include, val)
						case "max-redirections":
							iv, err := strconv.ParseInt(val, 10, 64)
							if err != nil {
								fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
								return fmt.Errorf("invalid")
							}
							opts.MaxRedirections = int(iv)
						case "timeout":
							iv, err := strconv.ParseInt(val, 10, 64)
							if err != nil {
								fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
								return fmt.Errorf("invalid")
							}
							opts.Timeout = int(iv)
						}
						break
					}
				} else {
					switch def.long {
					case "ignore-fragments":
						opts.IgnoreFragments = true
					case "verbose":
						opts.Verbose = true
					case "help":
						opts.Help = true
					}
					// continue to next short in same arg if any
				}
			}
		} else {
			// positional
			positional = append(positional, arg)
		}
		i++
	}

	if opts.Help {
		printHelp()
		return nil
	}
	if opts.Version {
		fmt.Println(version)
		return nil
	}

	// Validate accepted status codes
	acceptedCodes, err := parseAcceptedStatusCodes(opts.AcceptedStatusCodes)
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		return fmt.Errorf("invalid status codes")
	}

	// Validate headers
	for _, h := range opts.Headers {
		if !strings.Contains(h, ":") {
			fmt.Fprintln(os.Stderr, "invalid header format")
			return fmt.Errorf("invalid header")
		}
		parts := strings.SplitN(h, ":", 2)
		if strings.TrimSpace(parts[0]) == "" {
			// allow empty? But same as original: ": value" was accepted (it didn't error invalid header format)
			// So only check if no colon.
		}
		// If value after colon is empty? Original accepts "X-Test:"? We tested and it timed out because it tried to fetch example.com and maybe hung? Actually earlier test with "X-Test:" timed out. Let's see: we did --header "X-Test:" and it timed out when fetching example.com. So header with empty value after colon is accepted (at least not invalid header format).
		// So only check colon presence.
	}

	// Validate regexes
	for _, pat := range opts.Exclude {
		_, err := regexp.Compile(pat)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error parsing regexp: %v\n", err)
			return fmt.Errorf("invalid regex")
		}
	}
	for _, pat := range opts.Include {
		_, err := regexp.Compile(pat)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error parsing regexp: %v\n", err)
			return fmt.Errorf("invalid regex")
		}
	}

	// Validate positional
	if len(positional) != 1 {
		fmt.Fprintln(os.Stderr, "invalid number of arguments")
		return fmt.Errorf("invalid args")
	}
	rootURLStr := positional[0]

	// Check for deadlock cases: max-connections 0 or max-connections-per-host 0 causes deadlock in original.
