// Accepted status codes parsing

type codeRange struct {
	start int
	end   int // exclusive
}

func (r codeRange) Contains(code int) bool {
	return code >= r.start && code < r.end
}

func parseAcceptedStatusCodes(s string) ([]codeRange, error) {
	if s == "" {
		return nil, fmt.Errorf("invalid status code range: ")
	}
	parts := strings.Split(s, ",")
	var ranges []codeRange
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			return nil, fmt.Errorf("invalid status code range: %s", part)
		}
		if strings.Contains(part, "..") {
			sub := strings.Split(part, "..")
			if len(sub) != 2 {
				return nil, fmt.Errorf("invalid status code range: %s", part)
			}
			startStr := sub[0]
			endStr := sub[1]
			start, err := strconv.Atoi(startStr)
			if err != nil {
				return nil, fmt.Errorf("invalid status code: %s", startStr)
			}
			end, err := strconv.Atoi(endStr)
			if err != nil {
				return nil, fmt.Errorf("invalid status code: %s", endStr)
			}
			// If start == end, then range is empty? Original allowed "200..200" but it caused root page failure 200, meaning empty range, not error. So we allow start == end, producing empty range.
			// If start > end, what happens? Original allowed "201..200" without error? In our earlier test, "201..200" gave "failed to fetch root page: ..." not parsing error. So allow start > end, which would be empty or negative range? For simplicity, if start > end, treat as empty? Or treat as range with start > end meaning no codes? Let's allow.
			// But for Contains, if start > end, then no codes will match because start <= code < end impossible if start>end.
			ranges = append(ranges, codeRange{start: start, end: end})
		} else {
			// single code
			code, err := strconv.Atoi(part)
			if err != nil {
				return nil, fmt.Errorf("invalid status code range: %s", part)
			}
			ranges = append(ranges, codeRange{start: code, end: code + 1})
		}
	}
	return ranges, nil
}

func isTerminal() bool {
	// Try to use color.NoColor and isatty
	// Use os.Stdout stat
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	// If it's a terminal, ModeCharDevice
	return (fi.Mode() & os.ModeCharDevice) != 0
