func extractLinks(body []byte, base *url.URL) ([]string, string) {
	var links []string
	var baseHref string
	doc, err := html.Parse(bytes.NewReader(body))
	if err != nil {
		return links, baseHref
	}
	var traverse func(*html.Node)
	traverse = func(n *html.Node) {
		if n.Type == html.ElementNode {
			switch n.Data {
			case "a":
				for _, attr := range n.Attr {
					if attr.Key == "href" {
						links = append(links, attr.Val)
						break
					}
				}
			case "link":
				for _, attr := range n.Attr {
					if attr.Key == "href" {
						links = append(links, attr.Val)
						break
					}
				}
			case "script":
				for _, attr := range n.Attr {
					if attr.Key == "src" {
						links = append(links, attr.Val)
						break
					}
				}
			case "img":
				for _, attr := range n.Attr {
					if attr.Key == "src" {
						links = append(links, attr.Val)
						break
					}
				}
			case "source":
				for _, attr := range n.Attr {
					if attr.Key == "src" {
						links = append(links, attr.Val)
					}
					if attr.Key == "srcset" {
						// srcset can contain multiple URLs: e.g., "/img1.png 1x, /img2.png 2x"
						// Parse
						parts := strings.Split(attr.Val, ",")
						for _, p := range parts {
							p = strings.TrimSpace(p)
							if p == "" {
								continue
							}
							// URL is first token before space
							fields := strings.Fields(p)
							if len(fields) > 0 {
								links = append(links, fields[0])
							}
						}
					}
				}
			case "iframe":
				for _, attr := range n.Attr {
					if attr.Key == "src" {
						links = append(links, attr.Val)
						break
					}
				}
			case "track":
				for _, attr := range n.Attr {
					if attr.Key == "src" {
						links = append(links, attr.Val)
						break
					}
				}
			case "base":
				for _, attr := range n.Attr {
					if attr.Key == "href" {
						baseHref = attr.Val
						break
					}
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			traverse(c)
		}
	}
	traverse(doc)
	return links, baseHref
}
