				ctTarget := targetRes.Header.Get("Content-Type")
				isHTMLTarget := strings.Contains(ctTarget, "text/html") || strings.Contains(ctTarget, "application/xhtml+xml")
				if isHTMLTarget {
					visitedMu.Lock()
					if !visited[resolved.String()] {
						visited[resolved.String()] = true
						queueList = append(queueList, resolved)
					}
					visitedMu.Unlock()
				}
			}
		}

		sort.Slice(pageLinks, func(i, j int) bool {
			return pageLinks[i].URL < pageLinks[j].URL
		})

		resultsMu.Lock()
		results[curStr] = pageLinks
		resultsMu.Unlock()
	}

	useColor := false
	if opts.Color == "always" {
		useColor = true
	} else if opts.Color == "auto" {
		useColor = isTerminal()
	}

	switch format {
	case "text":
