			URL   string     `json:"url"`
			Links []jsonLink `json:"links"`
		}
		var pages []jsonPage
		pageURLs := make([]string, 0, len(results))
		for p := range results {
			pageURLs = append(pageURLs, p)
		}
		sort.Strings(pageURLs)
		for _, pageURL := range pageURLs {
			links := results[pageURL]
			var filtered []jsonLink
			if !isVerboseJson {
				for _, lr := range links {
					if lr.Error != "" {
						filtered = append(filtered, jsonLink{URL: lr.URL, Error: lr.Error})
					}
				}
				if len(filtered) == 0 {
					continue
				}
			} else {
				for _, lr := range links {
					if lr.Error != "" {
						filtered = append(filtered, jsonLink{URL: lr.URL, Error: lr.Error})
					} else {
						s := lr.StatusCode
						filtered = append(filtered, jsonLink{URL: lr.URL, Status: &s})
					}
				}
			}
			sort.Slice(filtered, func(i, j int) bool {
				return filtered[i].URL < filtered[j].URL
			})
			pages = append(pages, jsonPage{URL: pageURL, Links: filtered})
		}
		sort.Slice(pages, func(i, j int) bool {
			return pages[i].URL < pages[j].URL
		})
		if pages == nil {
			pages = []jsonPage{}
		}
		data, _ := json.Marshal(pages)
		fmt.Println(string(data))
		hasErr := false
		for _, links := range results {
			for _, lr := range links {
				if lr.Error != "" {
					hasErr = true
