type codeRange struct {
	start int
	end   int
}

func (r codeRange) Contains(code int) bool {
	return code >= r.start && code < r.end
}

func parseAcceptedStatusCodes(s string) ([]codeRange, error) {
	if s == "" {
		return nil, fmt.Errorf("invalid status code range: ")
	}
	parts := strings.Split(s, ",")
	var ranges []codeRange
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			return nil, fmt.Errorf("invalid status code range: %s", part)
		}
		if strings.Contains(part, "..") {
			sub := strings.Split(part, "..")
			if len(sub) != 2 {
				return nil, fmt.Errorf("invalid status code range: %s", part)
			}
			startStr := sub[0]
			endStr := sub[1]
			start, err := strconv.Atoi(startStr)
			if err != nil {
				return nil, fmt.Errorf("invalid status code: %s", startStr)
			}
			end, err := strconv.Atoi(endStr)
			if err != nil {
				return nil, fmt.Errorf("invalid status code: %s", endStr)
			}
			ranges = append(ranges, codeRange{start: start, end: end})
		} else {
			code, err := strconv.Atoi(part)
			if err != nil {
				return nil, fmt.Errorf("invalid status code range: %s", part)
			}
			ranges = append(ranges, codeRange{start: code, end: code + 1})
		}
	}
	return ranges, nil
}

func isTerminal() bool {
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func extractLinks(body []byte, base *url.URL) ([]string, string) {
	var links []string
	var baseHref string
	doc, err := html.Parse(bytes.NewReader(body))
	if err != nil {
		return links, baseHref
	}
	var traverse func(*html.Node)
	traverse = func(n *html.Node) {
		if n.Type == html.ElementNode {
			switch n.Data {
			case "a":
				for _, attr := range n.Attr {
					if attr.Key == "href" {
						links = append(links, attr.Val)
						break
					}
				}
			case "link":
				for _, attr := range n.Attr {
					if attr.Key == "href" {
						links = append(links, attr.Val)
						break
					}
				}
			case "script":
				for _, attr := range n.Attr {
					if attr.Key == "src" {
						links = append(links, attr.Val)
						break
					}
				}
			case "img":
				for _, attr := range n.Attr {
					if attr.Key == "src" {
						links = append(links, attr.Val)
						break
					}
				}
			case "source":
				for _, attr := range n.Attr {
					if attr.Key == "src" {
						links = append(links, attr.Val)
					}
					if attr.Key == "srcset" {
						parts := strings.Split(attr.Val, ",")
						for _, p := range parts {
							p = strings.TrimSpace(p)
							if p == "" {
								continue
							}
							fields := strings.Fields(p)
							if len(fields) > 0 {
								links = append(links, fields[0])
							}
						}
					}
				}
			case "iframe":
				for _, attr := range n.Attr {
					if attr.Key == "src" {
						links = append(links, attr.Val)
						break
					}
				}
			case "track":
				for _, attr := range n.Attr {
					if attr.Key == "src" {
						links = append(links, attr.Val)
						break
					}
				}
			case "base":
				for _, attr := range n.Attr {
					if attr.Key == "href" {
						baseHref = attr.Val
						break
					}
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			traverse(c)
		}
	}
	traverse(doc)
	return links, baseHref
}
