	for _, pat := range opts.Include {
		re, _ := regexp.Compile(pat)
		includeRegs = append(includeRegs, re)
	}

	shouldInclude := func(u string) bool {
		if len(includeRegs) > 0 {
			matched := false
			for _, re := range includeRegs {
				if re.MatchString(u) {
					matched = true
					break
				}
			}
			if !matched {
				return false
			}
		}
		for _, re := range excludeRegs {
			if re.MatchString(u) {
				return false
			}
		}
		return true
	}

	var resolver *net.Resolver
	if opts.DnsResolver != "" {
		dnsAddr := opts.DnsResolver
		resolver = &net.Resolver{
			PreferGo: true,
			Dial: func(ctx context.Context, network, address string) (net.Conn, error) {
				d := net.Dialer{Timeout: time.Duration(opts.Timeout) * time.Second}
				conn, err := d.DialContext(ctx, network, dnsAddr)
				if err != nil {
					return nil, err
				}
				return conn, nil
			},
		}
	} else {
		resolver = net.DefaultResolver
	}

	var proxyAddr string
	if opts.Proxy != "" {
		proxyStr := opts.Proxy
		var hostPort string
		if strings.Contains(proxyStr, "://") {
			u, err := url.Parse(proxyStr)
			if err != nil {
				fmt.Fprintf(os.Stderr, "failed to fetch root page: %v\n", err)
				return fmt.Errorf("proxy parse")
			}
			hostPort = u.Host
		} else {
			hostPort = proxyStr
		}
		if _, _, err := net.SplitHostPort(hostPort); err != nil {
			if strings.Contains(err.Error(), "missing port") {
				fmt.Fprintf(os.Stderr, "failed to fetch root page: address %s: missing port in address\n", hostPort)
				return fmt.Errorf("proxy missing port")
			}
			fmt.Fprintf(os.Stderr, "failed to fetch root page: %v\n", err)
			return fmt.Errorf("proxy error")
		}
		proxyAddr = hostPort
	}

	baseDialer := &net.Dialer{
		Timeout:  time.Duration(opts.Timeout) * time.Second,
		Resolver: resolver,
	}

	var rateLimiter *time.Ticker
	if opts.RateLimit > 0 {
		interval := time.Second / time.Duration(opts.RateLimit)
		if interval == 0 {
			interval = time.Nanosecond
		}
		rateLimiter = time.NewTicker(interval)
	}

	transport := &http.Transport{
		TLSClientConfig: &tls.Config{
			InsecureSkipVerify: opts.SkipTLSVerification,
		},
		DisableKeepAlives: true,
		DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
			if proxyAddr != "" {
				conn, err := baseDialer.DialContext(ctx, network, proxyAddr)
				if err != nil {
					return nil, err
				}
				connectReq := fmt.Sprintf("CONNECT %s HTTP/1.1\r\nHost: %s\r\n\r\n", addr, addr)
				_, err = conn.Write([]byte(connectReq))
				if err != nil {
					conn.Close()
					return nil, err
				}
				br := bufio.NewReader(conn)
				line, err := br.ReadString('\n')
				if err != nil {
					conn.Close()
					return nil, err
				}
				parts := strings.Split(line, " ")
				if len(parts) < 2 {
					conn.Close()
					return nil, fmt.Errorf("invalid proxy response")
				}
				code, _ := strconv.Atoi(parts[1])
				for {
					l, err := br.ReadString('\n')
					if err != nil {
						conn.Close()
						return nil, err
					}
					if l == "\r\n" || l == "\n" {
						break
					}
				}
				if code != 200 {
					conn.Close()
					return nil, fmt.Errorf("could not connect to proxyAddr: %s status code: %d", proxyAddr, code)
				}
				return conn, nil
			}
			if rateLimiter != nil {
				<-rateLimiter.C
			}
			return baseDialer.DialContext(ctx, network, addr)
		},
	}

	client := &http.Client{
		Transport: transport,
		Timeout:   time.Duration(opts.Timeout) * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			return http.ErrUseLastResponse
		},
	}

	type fetchResult struct {
		URL        *url.URL
		StatusCode int
		Body       []byte
		Header     http.Header
		FinalURL   *url.URL
		Err        error
	}

	unwrapURLError := func(err error) error {
		if urlErr, ok := err.(*url.Error); ok {
			return urlErr.Err
		}
		// Try errors.As for wrapped
		// We avoid importing errors, use type switch
		return err
	}

	fetch := func(u *url.URL) fetchResult {
		var lastErr error
		for attempt := 0; attempt <= int(opts.MaxRetries); attempt++ {
			req, err := http.NewRequest("GET", u.String(), nil)
			if err != nil {
				return fetchResult{URL: u, Err: err}
			}
			for k, vals := range headerMap {
				for _, v := range vals {
					req.Header.Add(k, v)
				}
			}
			if req.Header.Get("Accept") == "" {
				req.Header.Set("Accept", "*/*")
			}
			resp, err := client.Do(req)
			if err != nil {
				err = unwrapURLError(err)
				errStr := err.Error()
				if strings.Contains(errStr, "too many redirections") {
					return fetchResult{URL: u, Err: fmt.Errorf("too many redirections")}
				}
				if attempt < int(opts.MaxRetries) {
					lastErr = err
					continue
				}
				if strings.Contains(errStr, "could not connect to proxyAddr") {
					return fetchResult{URL: u, Err: err}
				}
				if strings.Contains(errStr, "lookup") {
					return fetchResult{URL: u, Err: err}
				}
				if opts.Timeout == 0 && (strings.Contains(errStr, "timeout") || strings.Contains(errStr, "deadline")) {
					return fetchResult{URL: u, Err: fmt.Errorf("timeout")}
				}
				if strings.Contains(errStr, "dial") {
					for _, prefix := range []string{"dial tcp ", "dial udp "} {
						if idx := strings.Index(errStr, prefix); idx != -1 {
							rest := errStr[idx+len(prefix):]
							if sepIdx := strings.Index(rest, ": "); sepIdx != -1 {
								addrPart := rest[:sepIdx]
								return fetchResult{URL: u, Err: fmt.Errorf("error when dialing %s: %s", addrPart, err)}
							}
						}
					}
					defaultPort := "80"
					if u.Scheme == "https" {
						defaultPort = "443"
					}
					hp := u.Host
					if _, _, err2 := net.SplitHostPort(hp); err2 != nil {
						hp = net.JoinHostPort(hp, defaultPort)
					}
					return fetchResult{URL: u, Err: fmt.Errorf("error when dialing %s: %s", hp, err)}
				}
				return fetchResult{URL: u, Err: err}
			}
			if resp.StatusCode >= 300 && resp.StatusCode < 400 {
				loc := resp.Header.Get("Location")
				if loc == "" {
					resp.Body.Close()
					return fetchResult{URL: u, Err: fmt.Errorf("location header not set")}
				}
			}
			var bodyBuf bytes.Buffer
			limitedReader := io.LimitReader(resp.Body, int64(opts.MaxResponseBodySize)+1)
			n, err := io.Copy(&bodyBuf, limitedReader)
			resp.Body.Close()
			if err != nil {
				if attempt < int(opts.MaxRetries) {
					lastErr = err
					continue
				}
				return fetchResult{URL: u, Err: err}
			}
			if n > int64(opts.MaxResponseBodySize) {
				return fetchResult{URL: u, Err: fmt.Errorf("body size exceeds the given limit")}
			}
			body := bodyBuf.Bytes()
			return fetchResult{
				URL:        u,
				StatusCode: resp.StatusCode,
				Body:       body,
				Header:     resp.Header,
				FinalURL:   resp.Request.URL,
				Err:        nil,
			}
		}
		return fetchResult{URL: u, Err: lastErr}
	}

	fetchWithRedirectInfo := func(u *url.URL) fetchResult {
		currentURL := u
		for redirectCount := 0; redirectCount <= opts.MaxRedirections; redirectCount++ {
			res := fetch(currentURL)
			if res.Err != nil {
				if redirectCount > 0 && strings.HasPrefix(res.Err.Error(), "error when dialing") {
					newErr := fmt.Errorf("%s (following redirect %s)", res.Err.Error(), currentURL.String())
					res.Err = newErr
				}
				return res
			}
			if res.StatusCode >= 300 && res.StatusCode < 400 {
				loc := res.Header.Get("Location")
				if loc == "" {
					return fetchResult{URL: currentURL, Err: fmt.Errorf("location header not set")}
				}
				locURL, err := url.Parse(loc)
				if err != nil {
					return fetchResult{URL: currentURL, Err: err}
				}
				nextURL := currentURL.ResolveReference(locURL)
				if redirectCount >= opts.MaxRedirections {
					return fetchResult{URL: currentURL, Err: fmt.Errorf("too many redirections")}
				}
				currentURL = nextURL
				continue
			}
			res.FinalURL = currentURL
			return res
		}
		return fetchResult{URL: currentURL, Err: fmt.Errorf("too many redirections")}
	}

	if opts.FollowRobotsTxt {
		robotsURLStr := fmt.Sprintf("%s://%s/robots.txt", parsedRoot.Scheme, parsedRoot.Host)
		robotsURL, _ := url.Parse(robotsURLStr)
		res := fetchWithRedirectInfo(robotsURL)
		if res.Err != nil {
			fmt.Fprintf(os.Stderr, "failed to fetch robots.txt: %v\n", res.Err)
			return fmt.Errorf("robots")
		}
		if res.StatusCode < 200 || res.StatusCode >= 300 {
			fmt.Fprintf(os.Stderr, "failed to fetch robots.txt: %d\n", res.StatusCode)
			return fmt.Errorf("robots")
		}
	}

	if opts.FollowSitemapXml {
		sitemapURLStr := fmt.Sprintf("%s://%s/sitemap.xml", parsedRoot.Scheme, parsedRoot.Host)
		sitemapURL, _ := url.Parse(sitemapURLStr)
		res := fetchWithRedirectInfo(sitemapURL)
		if res.Err != nil {
			fmt.Fprintf(os.Stderr, "failed to GET sitemap.xml: %v\n", res.Err)
			return fmt.Errorf("sitemap")
		}
		if res.StatusCode < 200 || res.StatusCode >= 300 {
			fmt.Fprintf(os.Stderr, "failed to GET sitemap.xml: %d\n", res.StatusCode)
			return fmt.Errorf("sitemap")
		}
	}

	type linkResult struct {
		URL        string
		StatusCode int
		Error      string
	}

	var (
		visited   = make(map[string]bool)
		results   = make(map[string][]linkResult)
		visitedMu sync.Mutex
		resultsMu sync.Mutex
	)

	semChan := make(chan struct{}, opts.MaxConnections)
	if opts.MaxConnections <= 0 {
		semChan = make(chan struct{}, 1)
	}
	hostSemMap := make(map[string]chan struct{})
	hostSemMapMu := sync.Mutex{}

	getHostSem := func(host string) chan struct{} {
		hostSemMapMu.Lock()
		defer hostSemMapMu.Unlock()
		if ch, ok := hostSemMap[host]; ok {
			return ch
		}
		ch := make(chan struct{}, opts.MaxConnectionsPerHost)
		if opts.MaxConnectionsPerHost <= 0 {
			ch = make(chan struct{}, 1)
		}
		hostSemMap[host] = ch
		return ch
	}

	shouldCrawl := func(u *url.URL) bool {
		if opts.OnePageOnly {
			return false
		}
		if u.Host != parsedRoot.Host {
			return false
		}
		return true
	}

	fetchCache := make(map[string]fetchResult)
	fetchCacheMu := sync.Mutex{}

	fetchWithCache := func(u *url.URL) fetchResult {
		uStr := u.String()
		fetchCacheMu.Lock()
		if res, ok := fetchCache[uStr]; ok {
			fetchCacheMu.Unlock()
			return res
		}
		fetchCacheMu.Unlock()

		semChan <- struct{}{}
		hostSem := getHostSem(u.Host)
		hostSem <- struct{}{}

		res := fetchWithRedirectInfo(u)

		<-hostSem
		<-semChan

		fetchCacheMu.Lock()
		fetchCache[uStr] = res
		fetchCacheMu.Unlock()
		return res
	}

	hasFragment := func(body []byte, frag string) bool {
		if frag == "" {
			return true
		}
		doc, err := html.Parse(bytes.NewReader(body))
		if err != nil {
			return false
		}
		found := false
		var trav func(*html.Node)
		trav = func(n *html.Node) {
			if found {
				return
			}
			if n.Type == html.ElementNode {
				for _, attr := range n.Attr {
					if attr.Key == "id" && attr.Val == frag {
						found = true
						return
					}
					if attr.Key == "name" && attr.Val == frag {
						found = true
						return
					}
				}
			}
			for c := n.FirstChild; c != nil; c = c.NextSibling {
				trav(c)
			}
		}
		trav(doc)
		return found
	}

	queueList := []*url.URL{parsedRoot}
	visited[parsedRoot.String()] = true

	rootRes := fetchWithCache(parsedRoot)
	if rootRes.Err != nil {
		fmt.Fprintf(os.Stderr, "failed to fetch root page: %v\n", rootRes.Err)
		os.Exit(1)
	}
	isAcceptedRoot := false
	for _, r := range acceptedCodes {
		if r.Contains(rootRes.StatusCode) {
			isAcceptedRoot = true
			break
		}
	}
	if !isAcceptedRoot {
		fmt.Fprintf(os.Stderr, "failed to fetch root page: %d\n", rootRes.StatusCode)
		os.Exit(1)
	}
	ctRoot := rootRes.Header.Get("Content-Type")
	if !strings.Contains(ctRoot, "text/html") && !strings.Contains(ctRoot, "application/xhtml+xml") {
		fmt.Fprintln(os.Stderr, "root page has invalid content type")
		os.Exit(1)
	}

	for len(queueList) > 0 {
		curURL := queueList[0]
		queueList = queueList[1:]
		curStr := curURL.String()

		curRes := fetchWithCache(curURL)
		if curRes.Err != nil {
			continue
		}
		ct := curRes.Header.Get("Content-Type")
		isHTML := strings.Contains(ct, "text/html") || strings.Contains(ct, "application/xhtml+xml")
		if !isHTML {
			resultsMu.Lock()
			results[curStr] = []linkResult{}
			resultsMu.Unlock()
			continue
		}

		links, baseHref := extractLinks(curRes.Body, curURL)
		seen := make(map[string]bool)
		pageLinks := []linkResult{}

		baseURLForResolving := curURL
		if baseHref != "" {
			b, err := url.Parse(baseHref)
			if err == nil {
				baseURLForResolving = baseURLForResolving.ResolveReference(b)
			}
		}

		for _, raw := range links {
			if strings.TrimSpace(raw) == "" {
				continue
			}
			parsedLink, err := url.Parse(raw)
			if err != nil {
				continue
			}
			resolved := baseURLForResolving.ResolveReference(parsedLink)
			if resolved.Scheme != "http" && resolved.Scheme != "https" {
				if resolved.Scheme != "" {
					continue
				}
				resolved.Scheme = baseURLForResolving.Scheme
			}
			frag := resolved.Fragment
			resolved.Fragment = ""

			if resolved.String() == "" {
				continue
			}

			reportURL := resolved.String()
			if frag != "" {
				reportURL = reportURL + "#" + frag
			}

			if !shouldInclude(reportURL) && !shouldInclude(resolved.String()) {
				continue
			}

			if seen[reportURL] {
				continue
			}
			seen[reportURL] = true

			targetRes := fetchWithCache(resolved)

			if targetRes.Err != nil {
				pageLinks = append(pageLinks, linkResult{
					URL:   reportURL,
					Error: targetRes.Err.Error(),
				})
				continue
			}

			accepted := false
			for _, r := range acceptedCodes {
				if r.Contains(targetRes.StatusCode) {
					accepted = true
					break
				}
			}
			if !accepted {
				pageLinks = append(pageLinks, linkResult{
					URL:        reportURL,
					StatusCode: targetRes.StatusCode,
					Error:      fmt.Sprintf("%d", targetRes.StatusCode),
				})
				continue
			}

			if frag != "" && !opts.IgnoreFragments {
				ctTarget := targetRes.Header.Get("Content-Type")
				isHTMLTarget := strings.Contains(ctTarget, "text/html") || strings.Contains(ctTarget, "application/xhtml+xml")
				if isHTMLTarget {
					if !hasFragment(targetRes.Body, frag) {
						pageLinks = append(pageLinks, linkResult{
							URL:   reportURL,
							Error: fmt.Sprintf("id #%s not found", frag),
						})
						continue
					}
				}
				pageLinks = append(pageLinks, linkResult{
					URL:        reportURL,
					StatusCode: targetRes.StatusCode,
				})
			} else {
				pageLinks = append(pageLinks, linkResult{
					URL:        reportURL,
					StatusCode: targetRes.StatusCode,
				})
			}

			if shouldCrawl(resolved) {
				ctTarget := targetRes.Header.Get("Content-Type")
				isHTMLTarget := strings.Contains(ctTarget, "text/html") || strings.Contains(ctTarget, "application/xhtml+xml")
				if isHTMLTarget {
					visitedMu.Lock()
					if !visited[resolved.String()] {
						visited[resolved.String()] = true
						queueList = append(queueList, resolved)
					}
					visitedMu.Unlock()
				}
			}
		}

		sort.Slice(pageLinks, func(i, j int) bool {
			return pageLinks[i].URL < pageLinks[j].URL
		})

		resultsMu.Lock()
		results[curStr] = pageLinks
		resultsMu.Unlock()
	}

	useColor := false
	if opts.Color == "always" {
		useColor = true
	} else if opts.Color == "auto" {
		useColor = isTerminal()
	}

	switch format {
	case "text":
		pages := make([]string, 0, len(results))
		for p := range results {
			pages = append(pages, p)
		}
		sort.Strings(pages)
		for _, pageURL := range pages {
			links := results[pageURL]
			if !isVerbose {
				hasError := false
				for _, lr := range links {
					if lr.Error != "" {
						hasError = true
						break
					}
				}
				if !hasError {
					continue
				}
			}
			if useColor {
				fmt.Printf("\033[33m%s\033[0m\n", pageURL)
			} else {
				fmt.Printf("%s\n", pageURL)
			}
			for _, lr := range links {
				if !isVerbose && lr.Error == "" {
					continue
				}
				statusStr := ""
				if lr.Error != "" {
					statusStr = lr.Error
				} else {
					statusStr = strconv.Itoa(lr.StatusCode)
				}
				if useColor {
					if lr.Error != "" {
						statusStr = "\033[31m" + statusStr + "\033[0m"
					} else {
						statusStr = "\033[32m" + statusStr + "\033[0m"
					}
				}
				fmt.Printf("\t%s\t%s\n", statusStr, lr.URL)
			}
		}
		hasError := false
		for _, links := range results {
			for _, lr := range links {
				if lr.Error != "" {
					hasError = true
					break
				}
			}
			if hasError {
				break
			}
		}
		if hasError {
			os.Exit(1)
		} else {
			os.Exit(0)
		}
	case "json":
		type jsonLink struct {
			URL    string `json:"url"`
			Status *int   `json:"status,omitempty"`
			Error  string `json:"error,omitempty"`
		}
		type jsonPage struct {
			URL   string     `json:"url"`
			Links []jsonLink `json:"links"`
		}
		pages := []jsonPage{}
		pageURLs := make([]string, 0, len(results))
		for p := range results {
			pageURLs = append(pageURLs, p)
		}
		sort.Strings(pageURLs)
		for _, pageURL := range pageURLs {
			links := results[pageURL]
			filtered := []jsonLink{}
			if !isVerboseJson {
				for _, lr := range links {
					if lr.Error != "" {
						filtered = append(filtered, jsonLink{URL: lr.URL, Error: lr.Error})
					}
				}
				if len(filtered) == 0 {
					continue
				}
			} else {
				for _, lr := range links {
					if lr.Error != "" {
						filtered = append(filtered, jsonLink{URL: lr.URL, Error: lr.Error})
					} else {
						s := lr.StatusCode
						filtered = append(filtered, jsonLink{URL: lr.URL, Status: &s})
					}
				}
			}
			sort.Slice(filtered, func(i, j int) bool {
				return filtered[i].URL < filtered[j].URL
			})
			pages = append(pages, jsonPage{URL: pageURL, Links: filtered})
		}
		sort.Slice(pages, func(i, j int) bool {
			return pages[i].URL < pages[j].URL
		})
		if pages == nil {
			pages = []jsonPage{}
		}
		data, _ := json.Marshal(pages)
		fmt.Println(string(data))
		hasErr := false
		for _, links := range results {
			for _, lr := range links {
				if lr.Error != "" {
					hasErr = true
					break
				}
			}
			if hasErr {
				break
			}
		}
		if hasErr {
			os.Exit(1)
		} else {
			os.Exit(0)
		}
	case "junit":
		type Failure struct {
			Message string `xml:"message,attr"`
		}
		type TestCase struct {
			XMLName   xml.Name `xml:"testcase"`
			Name      string   `xml:"name,attr"`
			ClassName string   `xml:"classname,attr"`
			Failure   *Failure `xml:"failure,omitempty"`
		}
		type TestSuite struct {
			XMLName   xml.Name   `xml:"testsuite"`
			Name      string     `xml:"name,attr"`
			Tests     int        `xml:"tests,attr"`
			Failures  int        `xml:"failures,attr"`
			Skipped   int        `xml:"skipped,attr"`
			TestCases []TestCase `xml:"testcase"`
		}
		type TestSuites struct {
			XMLName    xml.Name    `xml:"testsuites"`
			TestSuites []TestSuite `xml:"testsuite"`
		}
		pageURLs := make([]string, 0, len(results))
		for p := range results {
			pageURLs = append(pageURLs, p)
		}
		sort.Strings(pageURLs)
		var suites []TestSuite
		for _, pageURL := range pageURLs {
			links := results[pageURL]
			sort.Slice(links, func(i, j int) bool {
				return links[i].URL < links[j].URL
			})
			testCases := []TestCase{}
			failures := 0
			for _, lr := range links {
				tc := TestCase{
					Name:      lr.URL,
					ClassName: pageURL,
				}
				if lr.Error != "" {
					tc.Failure = &Failure{Message: lr.Error}
					failures++
				}
				testCases = append(testCases, tc)
			}
			suite := TestSuite{
				Name:      pageURL,
				Tests:     len(testCases),
				Failures:  failures,
				Skipped:   0,
				TestCases: testCases,
			}
			suites = append(suites, suite)
		}
		sort.Slice(suites, func(i, j int) bool {
			return suites[i].Name < suites[j].Name
		})
		output := TestSuites{TestSuites: suites}
