		enc.Indent("", "  ")
		enc.Encode(output)
		hasFail := false
		for _, s := range suites {
			if s.Failures > 0 {
				hasFail = true
				break
			}
		}
		if hasFail {
			os.Exit(1)
		} else {
			os.Exit(0)
		}
	}

