type codeRange struct {
	start int
	end   int
}

func (r codeRange) Contains(code int) bool {
	return code >= r.start && code < r.end
}

func parseAcceptedStatusCodes(s string) ([]codeRange, error) {
	if s == "" {
		return nil, fmt.Errorf("invalid status code range: ")
	}
	parts := strings.Split(s, ",")
	var ranges []codeRange
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			return nil, fmt.Errorf("invalid status code range: %s", part)
		}
		if strings.Contains(part, "..") {
			sub := strings.Split(part, "..")
			if len(sub) != 2 {
				return nil, fmt.Errorf("invalid status code range: %s", part)
			}
			startStr := sub[0]
			endStr := sub[1]
			start, err := strconv.Atoi(startStr)
			if err != nil {
				return nil, fmt.Errorf("invalid status code: %s", startStr)
			}
			end, err := strconv.Atoi(endStr)
			if err != nil {
				return nil, fmt.Errorf("invalid status code: %s", endStr)
			}
			ranges = append(ranges, codeRange{start: start, end: end})
		} else {
			code, err := strconv.Atoi(part)
			if err != nil {
				return nil, fmt.Errorf("invalid status code range: %s", part)
			}
			ranges = append(ranges, codeRange{start: code, end: code + 1})
		}
	}
	return ranges, nil
}

func isTerminal() bool {
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

var (
	hrefRegex    = regexp.MustCompile(`(?i)(?:href|src)\s*=\s*["']?([^"'\s>]+)`)
	srcsetRegex  = regexp.MustCompile(`(?i)srcset\s*=\s*["']([^"']+)["']`)
	baseHrefRegex = regexp.MustCompile(`(?i)<base[^>]*href\s*=\s*["']?([^"'\s>]+)`)
)

func extractLinks(body []byte, base *url.URL) ([]string, string) {
	s := string(body)
	var links []string

	// Find base href
	baseHref := ""
	if m := baseHrefRegex.FindStringSubmatch(s); len(m) > 1 {
		baseHref = m[1]
	}

	// Very simple extraction: find all tags and parse attributes we care about
	// For <a>, <link>, <script>, <img>, <iframe>, <track>, <source>

	// Use regex to find tags
	// We'll use a simple approach: find all href/src/srcset occurrences in relevant tags
	// To be more accurate, we will match tag patterns

	// Patterns for each tag
	patterns := []string{
		`(?i)<a[^>]*href\s*=\s*["']?([^"'\s>]+)`,
		`(?i)<link[^>]*href\s*=\s*["']?([^"'\s>]+)`,
		`(?i)<script[^>]*src\s*=\s*["']?([^"'\s>]+)`,
		`(?i)<img[^>]*src\s*=\s*["']?([^"'\s>]+)`,
		`(?i)<iframe[^>]*src\s*=\s*["']?([^"'\s>]+)`,
		`(?i)<track[^>]*src\s*=\s*["']?([^"'\s>]+)`,
		`(?i)<source[^>]*src\s*=\s*["']?([^"'\s>]+)`,
	}

	for _, pat := range patterns {
		re := regexp.MustCompile(pat)
		matches := re.FindAllStringSubmatch(s, -1)
		for _, m := range matches {
			if len(m) > 1 {
				links = append(links, m[1])
			}
		}
	}

	// srcset handling for <source> and also <img> srcset? But earlier we saw img srcset not supported, only source srcset is.
	// However to be safe, we will extract srcset from source only, but also for any tag we already extracted src, we will also check srcset
	// Use srcsetRegex
	srcsetMatches := srcsetRegex.FindAllStringSubmatch(s, -1)
	for _, m := range srcsetMatches {
		if len(m) > 1 {
			// Check if this srcset is inside <source> tag? Simple: check if preceding text contains <source within last 100 chars
			// For simplicity, we will handle all srcset as if they are from source (since img srcset was not supported, but we will still include it? In original, img srcset was NOT supported, so we should NOT include img srcset. So we need to differentiate.
			// We will look for <source ... srcset and <img ... srcset separately
			// Let's do more precise: find <source[^>]*srcset
			// Already handled via patterns? We handled srcset for source via separate regex, but we also need to parse its values
			val := m[1]
			parts := strings.Split(val, ",")
			for _, p := range parts {
				p = strings.TrimSpace(p)
				if p == "" {
					continue
				}
				fields := strings.Fields(p)
				if len(fields) > 0 {
					// Only add if this srcset came from <source> tag
					// To check, find the position of this match and see if nearest tag is source
					// For simplicity, we will assume all srcset we found are from source, but we earlier tested img srcset not supported, so we need to exclude img srcset
					// We'll determine by checking if the match is inside <img> or <source>
					// We'll find index of match
					idx := strings.Index(s, m[0])
					// Look backwards for <
					start := idx - 200
					if start < 0 {
						start = 0
					}
					snippet := s[start:idx]
					// Find last < character
					lastLT := strings.LastIndex(snippet, "<")
					if lastLT != -1 {
						tagStart := snippet[lastLT:]
						if strings.Contains(strings.ToLower(tagStart), "<source") {
							links = append(links, fields[0])
						}
						// If it's <img>, skip (since img srcset not supported)
					} else {
						// No tag found, skip
					}
				}
			}
		}
	}

	return links, baseHref
}
