		Timeout:               10,
		Format:                "text",
		Color:                 "auto",
	}

	var positional []string
	longToDef := map[string]flagDef{}
	shortToDef := map[rune]flagDef{}
	for _, d := range flagDefs {
		longToDef[d.long] = d
		if d.short != 0 {
			shortToDef[d.short] = d
		}
	}

	invalidArgError := func(def flagDef, val string, err error) string {
		var flagRepr string
		if def.short != 0 {
			flagRepr = fmt.Sprintf("`-%c, --%s'", def.short, def.long)
		} else {
			flagRepr = fmt.Sprintf("`--%s'", def.long)
		}
		return fmt.Sprintf("invalid argument for flag %s (expected %s): %v", flagRepr, def.valueType, err)
	}

	invalidValueError := func(long, val string, allowed []string) string {
		allowedStr := ""
		if len(allowed) == 3 {
			allowedStr = fmt.Sprintf("%s, %s or %s", allowed[0], allowed[1], allowed[2])
		} else {
			allowedStr = strings.Join(allowed, ", ")
		}
		return fmt.Sprintf("Invalid value `%s' for option `--%s'. Allowed values are: %s", val, long, allowedStr)
	}

	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			positional = append(positional, args[i+1:]...)
			break
		}
		if strings.HasPrefix(arg, "--") {
			nameVal := arg[2:]
			var name, val string
			hasEq := false
			if idx := strings.Index(nameVal, "="); idx != -1 {
				name = nameVal[:idx]
				val = nameVal[idx+1:]
				hasEq = true
			} else {
				name = nameVal
			}
			def, ok := longToDef[name]
			if !ok {
				fmt.Fprintf(os.Stderr, "unknown flag `%s'\n", name)
				return fmt.Errorf("unknown flag")
			}
			if def.hasValue {
				if !hasEq {
					i++
					if i >= len(args) {
						fmt.Fprintf(os.Stderr, "expected argument for flag `--%s'\n", name)
						return fmt.Errorf("expected arg")
					}
					val = args[i]
				}
				switch def.long {
				case "accepted-status-codes":
					opts.AcceptedStatusCodes = val
				case "buffer-size":
					iv, err := strconv.ParseInt(val, 10, 64)
					if err != nil {
						fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
						return fmt.Errorf("invalid")
					}
					opts.BufferSize = int(iv)
				case "max-connections":
					iv, err := strconv.ParseInt(val, 10, 64)
					if err != nil {
						fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
						return fmt.Errorf("invalid")
					}
					opts.MaxConnections = int(iv)
				case "max-connections-per-host":
					iv, err := strconv.ParseInt(val, 10, 64)
					if err != nil {
						fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
						return fmt.Errorf("invalid")
					}
					opts.MaxConnectionsPerHost = int(iv)
				case "max-response-body-size":
					iv, err := strconv.ParseInt(val, 10, 64)
					if err != nil {
						fmt.Fprintln(os.Stderr, invalidArgError(def, val, err))
						return fmt.Errorf("invalid")
					}
					opts.MaxResponseBodySize = int(iv)
				case "exclude":
					opts.Exclude = append(opts.Exclude, val)
				case "include":
					opts.Include = append(opts.Include, val)
				case "header":
					opts.Headers = append(opts.Headers, val)
				case "max-retries":
